/bin/bash -lc "~/.venv/bin/python - <<'PY'
import importlib.util, pathlib, onnx, onnxruntime as ort
p=pathlib.Path('tasks/task010/build_task010.py')
s=importlib.util.spec_from_file_location('b',p); m=importlib.util.module_from_spec(s); s.loader.exec_module(m)
model=m.build_model()
for n in model.graph.node:
    if n.op_type=='TopK': n.output[0]=''
for i,v in enumerate(model.graph.value_info):
    if v.name=='sorted_heights': del model.graph.value_info[i]; break
try:
    onnx.checker.check_model(model, full_check=True)
    print('checker accepted')
except Exception as e: print('checker rejected:', e)
try:
    ort.InferenceSession(model.SerializeToString(), providers=['CPUExecutionProvider'])
    print('ORT accepted')
except Exception as e: print('ORT rejected:', e)
PY"

